import { defineConfig } from 'vitepress'

const repoUrl = 'https://github.com/QwenAudio/qwen-audio-agent'

// The site tree is generated by scripts/sync-docs-site.mjs (see predocs:*
// hooks): English pages stay at the root, `*.zh.md` companions are mirrored
// under zh/.
//
// NOTE: themeConfig is serialized into the client bundle, so editLink.pattern
// must be self-contained — no closure over module-scope helpers or constants.
function editPattern({ relativePath }) {
  const source = relativePath.startsWith('zh/')
    ? relativePath.slice(3).replace(/\.md$/, '.zh.md')
    : relativePath
  return `https://github.com/QwenAudio/qwen-audio-agent/edit/main/docs/${source}`
}

